public 
enum NluError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case BundleLoad(msg: String
    )
    case ManifestInvalid(msg: String
    )
    case Tokenizer(msg: String
    )
    case ShapeMismatch(msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension NluError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNluError: FfiConverterRustBuffer {
    typealias SwiftType = NluError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NluError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .BundleLoad(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ManifestInvalid(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Tokenizer(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .ShapeMismatch(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NluError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .BundleLoad(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .ManifestInvalid(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Tokenizer(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .ShapeMismatch(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


